import fs from 'node:fs';import vm from 'node:vm';import assert from 'node:assert/strict';
const read=p=>fs.readFileSync(p,'utf8');
const data=[];const sheet={getLastRow:()=>data.length,appendRow:r=>data.push(r),getRange:(row,col,n,w)=>({getValues:()=>data.slice(row-1,row-1+n).map(r=>r.slice(col-1,col-1+w)),setValues:rs=>rs.forEach((r,i)=>data[row-1+i]=r)})};
let valid=true;
const c=vm.createContext({SpreadsheetApp:{getActiveSpreadsheet:()=>({getSheetByName:()=>data.length?sheet:null,insertSheet:()=>sheet})},LockService:{getScriptLock:()=>({tryLock:()=>true,releaseLock(){}})},oturumKaydi_:()=>valid?{no:'synthetic-1'}:null,kayitNoIle_:()=>({no:'synthetic-1'})});
vm.runInContext(read('portal/appsscript/EtkinlikSonuclari.gs'),c);
const save=vm.runInContext('soruCevabiKaydet',c),token='x'.repeat(73),base={activityId:'mat-toplamacikarma-1',contentVersion:1,attemptId:'synthetic_attempt_1',question:1,choices:[0]};
assert.equal(save(token,base).basarili,true);assert.equal(data.length,2);assert.equal(data[1][8],false);
assert.equal(save(token,base).basarili,true);assert.equal(data.length,2,'duplicate retry');
assert.equal(save(token,{...base,choices:[0,1]}).basarili,true);assert.equal(data.length,3);assert.equal(data[2][8],true);
assert.equal(save(token,base).basarili,true);assert.equal(data.length,3,'stale response');
assert.equal(save(token,{...base,choices:[1]}).basarili,false,'first answer cannot change');
for(const v of [{question:31},{choices:[4]},{contentVersion:2},{activityId:'other'},{choices:[]}])assert.equal(save(token,{...base,...v}).basarili,false);
valid=false;assert.equal(save(token,{...base,question:2}).basarili,false);assert.equal(data.length,3,'logout rejected');
for(const p of ['Matematik/toplamacikarmaproblem1.html','portal/appsscript/OgrenciGiris_Guncel.html','portal/ogretmen-rapor/OgretmenRapor.html'])for(const m of read(p).matchAll(/<script[^>]*>([\s\S]*?)<\/script>/g))new vm.Script(m[1]);
new vm.Script(read('portal/ogretmen-rapor/OgretmenRapor.gs'));
const game=read('Matematik/toplamacikarmaproblem1.html').match(/<script[^>]*>([\s\S]*?)<\/script>/)[1];
const messages=[];const gc=vm.createContext({window:{parent:{postMessage:e=>messages.push(e)},addEventListener(){}},document:{querySelector:()=>({innerHTML:''})},setInterval(){},scrollTo(){},alert(){}});
vm.runInContext(game,gc);vm.runInContext('pick(0);pick(1);',gc);assert.equal(messages.length,1,'double click ignored');
vm.runInContext('ans[0]=null;pick(1)',gc);assert.deepEqual(Array.from(messages.at(-1).choices),[0,1]);assert.equal(vm.runInContext('firstAnswers[0]',gc),0);
vm.runInContext('reset();pick(1)',gc);assert.deepEqual(Array.from(messages.at(-1).choices),[1]);
const answers=vm.runInContext('Q.map(q=>q.a)',gc);assert.deepEqual(Array.from(answers),Array.from(vm.runInContext('SORU_PILOT_CEVAPLAR_',c)));
